(() => { if (!window.Hls || Hls.__tsCheckPatched) return; const buildCheckParam = (url) => { const parsedUrl = new URL(url, window.location.href); const requestId = parsedUrl.searchParams.get('request_id') ?? ''; const uid = parsedUrl.searchParams.get('uid') ?? ''; const expires = parsedUrl.searchParams.get('expires') ?? ''; return `${requestId.slice(0, 4)}${uid.slice(2, 6)}${expires.slice(-4)}`; }; const appendCheckParam = (url) => { const parsedUrl = new URL(url, window.location.href); parsedUrl.searchParams.set('check', buildCheckParam(parsedUrl.toString())); return parsedUrl.toString(); }; window.__hlsCheck = window.__hlsCheck ?? { buildCheckParam, appendCheckParam }; const BaseLoader = Hls.DefaultConfig.loader; class TsParamLoader extends BaseLoader { load(context, config, callbacks) { if (context?.url?.includes('.ts')) { context.url = appendCheckParam(context.url); } super.load(context, config, callbacks); } } Hls.DefaultConfig.loader = TsParamLoader; Hls.__tsCheckPatched = true;
})();
